    // #5b pin — `<[T]>::contains` gated on a std-total-`PartialEq` element `T`. This
    // pins the TWO soundness sub-gates purely (the full recognizer additionally reads
    // the receiver operand's slice element from `ctx`, exercised end-to-end by the
    // gate). Census element spellings: `[(bool, String)]`, `[String]`.
    #[test]
    fn slice_contains_recognizer_gates_are_sound() {
        use trust_types::Ty;
        // NAME GATE — the monomorphized census spellings normalize (strip_generics
        // erases the `<impl [T]>` receiver) to `core::slice::contains`, which is
        // std-root-anchored AND ends in `::slice::contains`.
        for callee in [
            "core::slice::<impl [(bool, alloc::string::String)]>::contains",
            "core::slice::<impl [alloc::string::String]>::contains",
            "core::slice::<impl [u32]>::contains",
        ] {
            let normalized = strip_generics(callee);
            assert!(
                has_trusted_std_root(&normalized) && normalized.ends_with("::slice::contains"),
                "slice::contains name gate must accept `{callee}` (normalized `{normalized}`)"
            );
        }
        // NO OVERLAP with the str Pattern `contains` (a DIFFERENT path handled by
        // `total_str_pattern_search_call`): it normalizes to `core::str::contains`,
        // which does NOT end in `::slice::contains`.
        let str_norm = strip_generics("core::str::<impl str>::contains");
        assert!(
            !str_norm.ends_with("::slice::contains"),
            "str::contains must NOT be routed to the slice recognizer"
        );
        // A user-namespace slice `contains` fails the std-root anchor.
        assert!(!has_trusted_std_root(&strip_generics(
            "mycrate::slice::<impl [u32]>::contains"
        )));

        // ELEMENT GATE — `is_std_total_hash_eq_key_ty` (oracle-pinned). Accept the
        // census element types + a bare primitive; REJECT a user element type whose
        // `PartialEq::eq` is arbitrary user code that can panic (fail-closed).
        let string_ty = Ty::adt("alloc::string::String", vec![]);
        assert!(is_std_total_hash_eq_key_ty(&string_ty));
        assert!(is_std_total_hash_eq_key_ty(&Ty::Tuple(vec![Ty::Bool, string_ty.clone()])));
        assert!(is_std_total_hash_eq_key_ty(&Ty::u32()));
        assert!(!is_std_total_hash_eq_key_ty(&Ty::adt("mycrate::Elem", vec![])));
        assert!(!is_std_total_hash_eq_key_ty(&Ty::Tuple(vec![
            Ty::Bool,
            Ty::adt("mycrate::Elem", vec![])
        ])));
    }

