    // Trust (W3.1/W3.4 soundness oracle): the print/format/write DISPATCH entry
    // points run arbitrary user `Display`/`Debug` code and CAN panic (or hit a broken
    // pipe). They must NEVER be classified total/no-panic — a false `total` here is a
    // false PROOF of panic-freedom.
    #[test]
    fn fmt_print_dispatch_is_never_total() {
        for callee in [
            "std::io::_print",
            "std::io::_eprint",
            "alloc::fmt::format",
            "core::fmt::write",
            "std::io::Write::write_fmt",
            "core::fmt::Write::write_fmt",
            "std::io::stdio::_print",
        ] {
            assert!(
                !total_no_panic_call_summary(callee),
                "print/format/write DISPATCH must never be summarized total: {callee}"
            );
        }
    }

    // Trust (W3.1 name-level regression): `_print`/`_eprint` must never be total even
    // though they live under `::io::` (the `::io::` totality blanket now excludes them
    // by name). Guards against a future re-broadening of the I/O blanket.
    #[test]
    fn io_print_backends_are_excluded_from_io_totality_blanket() {
        assert!(!total_no_panic_call_summary("std::io::_print"));
        assert!(!total_no_panic_call_summary("std::io::_eprint"));
        // A genuinely-total `::io::` accessor is still total (blanket otherwise intact).
        assert!(total_no_panic_call_summary("std::io::stdio::stdout"));
    }

    // Trust (W3.4): the dispatch oracle recognizes exactly the print/format/write
    // dispatch entry points as PANICKING (extern-call), and nothing else.
    #[test]
    fn extern_fmt_dispatch_oracle_accepts_dispatch_rejects_others() {
        for callee in [
            "std::io::_print",
            "std::io::_eprint",
            "alloc::fmt::format",
            "core::fmt::write",
            "std::io::Write::write_fmt",
            "core::fmt::Write::write_fmt",
        ] {
            assert!(extern_fmt_dispatch_call(callee), "expected extern dispatch: {callee}");
        }
        for callee in [
            // Pure packers are NOT dispatch (handled by `fmt_value_packing_call`).
            "core::fmt::rt::Argument::new_display",
            // Construction/query on Arguments is not a dispatch.
            "core::fmt::Arguments::new_const",
            // A user method merely named `format`/`write_fmt` is not core/alloc/std.
            "mycrate::thing::format",
            "mycrate::Writer::write_fmt",
            "core::str::<impl str>::len",
        ] {
            assert!(!extern_fmt_dispatch_call(callee), "must NOT be extern dispatch: {callee}");
        }
    }

    // Trust (W3.3 packing oracle): the `fmt` value-packing constructors are accepted
    // (they are pure packers, genuinely total), with the user-path anchor and the
    // deliberate `from_usize` exclusion pinned.
    #[test]
    fn fmt_value_packing_oracle_accept_reject() {
        for callee in [
            "core::fmt::rt::Argument::new_display",
            "core::fmt::rt::Argument::new_debug",
            "core::fmt::rt::Argument::new_lower_hex",
            "core::fmt::rt::Argument::<'_>::new_display",
            // The `Arguments` container constructors (every format-with-args call).
            "core::fmt::Arguments::new_v1",
            "core::fmt::Arguments::new_const",
            "core::fmt::Arguments::new_v1_formatted",
            "std::fmt::Arguments::<'a>::new",
        ] {
            assert!(fmt_value_packing_call(callee), "expected packing accept: {callee}");
            assert!(total_no_panic_call_summary(callee), "expected total: {callee}");
        }
        // `from_usize` panics on `> u16::MAX` — DELIBERATELY not a packer.
        assert!(!fmt_value_packing_call("core::fmt::rt::Argument::from_usize"));
        // User-path anchor: a same-named user type must fail closed (not core/alloc/std).
        assert!(!fmt_value_packing_call("mycrate::Argument::new_display"));
        assert!(!fmt_value_packing_call("mycrate::Arguments::new_v1"));
        // A dispatch call is not a packer.
        assert!(!fmt_value_packing_call("std::io::_print"));
    }

