    // Trust (FIX 1 — serde_json IMMUTABLE indexing name gate): the sealed
    // `serde_json::value::index::Index::index_into` (IMMUTABLE — `index_into(self)
    // .unwrap_or(&NULL)`, never panics) and the outer `<Value as
    // core::ops::index::Index<Idx>>::index` operator are name-authenticated by
    // `is_canonical_trait_method` on their EXACT crate-rooted trait paths, tolerating
    // the `::<__trust_args@HASH>` mono tag. The MUTABLE trio
    // `index_into_mut`/`index_or_insert`/`IndexMut::index_mut` (which PANIC on a
    // non-Object/Array receiver / missing key) are DISTINCT method symbols and match
    // NO immutable gate — LOCKING the soundness-critical immutable/mutable split so a
    // future edit cannot accidentally summarize a panicking mutable indexer.
    #[test]
    fn serde_json_index_into_immutable_only_name_gate() {
        // IMMUTABLE `index_into` — accepted in its real mono-tagged spelling (the
        // exact `<I as ...>` opaque-receiver form gateLCG.log reports) and bare.
        assert!(is_canonical_trait_method(
            "<I as serde_json::value::index::Index>::index_into::<__trust_args@1192fe1debfbf81f68197acc1bdfb826>",
            &["serde_json::value::index::Index"],
            "index_into",
        ));
        assert!(is_canonical_trait_method(
            "<usize as serde_json::value::index::Index>::index_into",
            &["serde_json::value::index::Index"],
            "index_into",
        ));
        // MUTABLE siblings — DISTINCT methods, must NOT match the `index_into` gate
        // (they panic on a non-Object/Array receiver, so summarizing them is a false
        // proof).
        for callee in [
            "<&str as serde_json::value::index::Index>::index_into_mut",
            "<&str as serde_json::value::index::Index>::index_or_insert::<__trust_args@abc123>",
        ] {
            assert!(
                !is_canonical_trait_method(
                    callee,
                    &["serde_json::value::index::Index"],
                    "index_into",
                ),
                "mutable sibling must NOT match index_into: {callee}"
            );
        }
        // The IMMUTABLE outer `Index::index` operator anchors to the canonical core
        // `Index` trait (the concrete `<Value as Index<&str>>::index` call that stays
        // absent once serde_json's `Value::index` is excluded from the bundle).
        assert!(is_canonical_trait_method(
            "<serde_json::value::Value as core::ops::index::Index<&str>>::index::<__trust_args@4182d63eb5d22017e356cda05a3f3fa0>",
            &["core::ops::index::Index", "core::ops::Index"],
            "index",
        ));
        // `IndexMut::index_mut` (MUTABLE operator, panics) must NOT match the
        // immutable `index` gate — `index` != `index_mut`.
        assert!(!is_canonical_trait_method(
            "<serde_json::value::Value as core::ops::index::IndexMut<&str>>::index_mut",
            &["core::ops::index::Index", "core::ops::Index"],
            "index",
        ));
        // User/spoof: a same-tail path on a DIFFERENT (non-serde_json) trait root
        // fails closed.
        assert!(!is_canonical_trait_method(
            "<MyIdx as mycrate::value::index::Index>::index_into",
            &["serde_json::value::index::Index"],
            "index_into",
        ));
    }

    // Trust (FIX 1 — serde_json sealed index-leaf gate): the LOAD-BEARING receiver
    // gate on the `index_into` discharge. serde_json's `value::index::Index` is
    // SEALED, implemented only for the FOREIGN leaves `usize`/`str`/`String` (and
    // `&T` — peeled), whose `index_into` is total. This gate DECLINES an UNSEALED
    // user receiver (a spoof crate's panicking `index_into` whose `self` is a local
    // type), so it must NOT be relaxed. Locks the accept-set and the user-ADT
    // fail-closed.
    #[test]
    fn serde_json_sealed_index_leaf_gate() {
        // Sealed leaves — accepted (references/raw-pointers peeled).
        assert!(is_serde_json_sealed_index_ty(&Ty::Str));
        assert!(is_serde_json_sealed_index_ty(&Ty::Int { width: 64, signed: false }));
        assert!(is_serde_json_sealed_index_ty(&Ty::PtrSizedInt { signed: false }));
        assert!(is_serde_json_sealed_index_ty(&Ty::Ref {
            mutable: false,
            inner: Box::new(Ty::Str),
        }));
        assert!(is_serde_json_sealed_index_ty(&Ty::adt("alloc::string::String", vec![])));
        assert!(is_serde_json_sealed_index_ty(&Ty::adt("std::string::String", vec![])));
        // UNSEALED user receiver — fails closed (the spoof's panicking index).
        assert!(!is_serde_json_sealed_index_ty(&Ty::adt("mycrate::LocalKey", vec![])));
        assert!(!is_serde_json_sealed_index_ty(&Ty::Float { width: 64 }));
        assert!(!is_serde_json_sealed_index_ty(&Ty::Char));
    }

